/* Day theme (default). Night theme applies when the root carries
   data-theme="night", or when the OS prefers dark and no theme is set. */
:root {
  --alert-bg: #fdf1ee;
  --alert-border: #d9826f;
  --alert-text: #5c1f12;
  --alert-icon-bg: #b5432c;
  --alert-icon-text: #fff8f6;
  --alert-button-bg: #b5432c;
  --alert-button-text: #fff8f6;
  --alert-button-hover: #963421;
  --alert-focus: #1f5fbf;
}

:root[data-theme="night"] {
  --alert-bg: #2a1714;
  --alert-border: #8a4537;
  --alert-text: #f6d6cd;
  --alert-icon-bg: #e0735b;
  --alert-icon-text: #1e0d0a;
  --alert-button-bg: #e0735b;
  --alert-button-text: #1e0d0a;
  --alert-button-hover: #ec8b76;
  --alert-focus: #8ab8ff;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="day"]) {
    --alert-bg: #2a1714;
    --alert-border: #8a4537;
    --alert-text: #f6d6cd;
    --alert-icon-bg: #e0735b;
    --alert-icon-text: #1e0d0a;
    --alert-button-bg: #e0735b;
    --alert-button-text: #1e0d0a;
    --alert-button-hover: #ec8b76;
    --alert-focus: #8ab8ff;
  }
}

.alert-banner {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--alert-border);
  border-radius: 8px;
  background: var(--alert-bg);
  color: var(--alert-text);
  font-family: inherit;
  font-size: 0.95rem;
  line-height: 1.4;
}

.alert-banner__icon {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  background: var(--alert-icon-bg);
  color: var(--alert-icon-text);
  font-weight: 700;
}

.alert-banner__message {
  flex: 1 1 auto;
  margin: 0;
  min-width: 0;
}

.alert-banner__retry {
  flex: 0 0 auto;
  padding: 0.4rem 0.9rem;
  border: 1px solid transparent;
  border-radius: 6px;
  background: var(--alert-button-bg);
  color: var(--alert-button-text);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.alert-banner__retry:hover {
  background: var(--alert-button-hover);
}

.alert-banner__retry:focus-visible {
  outline: 2px solid var(--alert-focus);
  outline-offset: 2px;
}
